<?php
declare(strict_types=1);
namespace Hostider\Support\Mail;
use Hostider\Core\{Id,CanonicalJson};
use Hostider\Core\Queue\{Outbox,Queue,Worker};
use Hostider\Core\Http\HttpError;
use Hostider\Core\Security\{Authorization,Principal};
use Hostider\Support\Access;
final readonly class Outbound
{
    public function __construct(private Common $m){}
    public function stage(array $t,?string $message,string $source,string $trace): void
    {
        $this->m->gate();$db=$this->m->c->db;$db->requireTransaction();if(!$db->execute('SELECT 1 FROM support_mail_retention WHERE department_id=? AND enabled=TRUE',[$t['department_id']])->fetchColumn()){return;}
        if(!$db->execute("SELECT 1 FROM support_events e JOIN support_messages m ON m.id=e.subject_id AND m.ticket_id=e.ticket_id AND m.customer_id=e.customer_id AND m.author_id=e.actor_id WHERE e.id=? AND e.ticket_id=? AND e.subject_id=? AND e.kind='STAFF_REPLY' AND m.type='staff_reply' AND m.customer_visible=TRUE",[$source,$t['id'],$message])->fetchColumn()){throw new HttpError(409,'MAIL_PUBLIC_EVENT_REQUIRED');}$id=Id::uuid();$db->execute("INSERT INTO support_mail_outbound(id,event_id,support_event_id,ticket_id,customer_id,message_id,message_ref,status) VALUES (?,?,?,?,?,?,?,'PENDING')",[$id,$id,$source,$t['id'],$t['customer_id'],$message,'<hd-'.$id.'@mock.hostider.invalid>']);(new Outbox($db,new Queue($db)))->append($id,'support.mail.ready',$t['id'],['event_uuid'=>$id,'support_event_uuid'=>$source,'ticket_id'=>$t['id'],'customer_id'=>$t['customer_id'],'message_id'=>$message],$trace);
    }
    public function register(Worker $w): void{$w->register('support.mail.ready',fn($p)=>$this->ready($p));$w->register('support.mail.dispatch',fn($p)=>$this->dispatch($p));}
    private function bound(array $p,string $type,bool $lock=false): ?array
    {
        $db=$this->m->c->db;$keys=array_keys($p);sort($keys,SORT_STRING);$expected=$type==='support.mail.ready'?['customer_id','event_uuid','message_id','support_event_uuid','ticket_id']:['delivery_id','event_uuid'];if($keys!==$expected){return null;}try{foreach($p as $v){Access::id($v);}}catch(HttpError){return null;}
        $o=$db->execute('SELECT o.payload,o.aggregate_id,j.payload AS jp,j.payload_fingerprint FROM outbox_events o JOIN jobs j ON j.dedupe_key=CONCAT(\'outbox:\',o.event_uuid) AND j.job_type=o.event_type WHERE o.event_uuid=? AND o.event_type=? AND o.published_at IS NOT NULL AND j.payload_purged_at IS NULL'.($lock?' FOR UPDATE':''),[$p['event_uuid'],$type])->fetch();if(!$o){return null;}$json=CanonicalJson::encode($p);if(CanonicalJson::fromJson($o['payload'])!==$json||CanonicalJson::fromJson($o['jp'])!==$json||!hash_equals(hash('sha256',$json),$o['payload_fingerprint']??'')){return null;}
        $id=$type==='support.mail.ready'?$p['event_uuid']:$p['delivery_id'];$r=$db->execute('SELECT * FROM support_mail_outbound WHERE id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$r||$o['aggregate_id']!==$r['ticket_id']){return null;}if($type==='support.mail.ready'){foreach(['event_id'=>'event_uuid','support_event_id'=>'support_event_uuid','ticket_id'=>'ticket_id','customer_id'=>'customer_id','message_id'=>'message_id'] as $column=>$key){if($r[$column]!==$p[$key]){return null;}}}else{$d=$db->execute('SELECT * FROM support_mail_dispatches WHERE event_id=? AND delivery_id=?'.($lock?' FOR UPDATE':''),[$p['event_uuid'],$id])->fetch();if(!$d){return null;}$r['dispatch']=$d;}
        if(!$db->execute("SELECT 1 FROM support_events e JOIN support_messages m ON m.id=e.subject_id AND m.ticket_id=e.ticket_id AND m.customer_id=e.customer_id AND m.author_id=e.actor_id JOIN support_tickets t ON t.id=e.ticket_id AND t.customer_id=e.customer_id WHERE e.id=? AND e.ticket_id=? AND e.customer_id=? AND e.subject_id=? AND e.kind='STAFF_REPLY' AND m.type='staff_reply' AND m.customer_visible=TRUE",[$r['support_event_id'],$r['ticket_id'],$r['customer_id'],$r['message_id']])->fetchColumn()){return null;}if($db->execute("SELECT 1 FROM support_merge_members WHERE ticket_id=? AND side='SOURCE'".($lock?' FOR UPDATE':''),[$r['ticket_id']])->fetchColumn()){return null;}return $r;
    }
    private function recipient(array $r): string
    {
        $db=$this->m->c->db;$t=$db->execute('SELECT * FROM support_tickets WHERE id=?',[$r['ticket_id']])->fetch();$u=$this->m->c->identity->repository->user($t['requester_id'],true);(new Access($this->m->c))->department($t['department_id']);$this->m->retention($t['department_id']);$locked=$db->execute('SELECT * FROM support_tickets WHERE id=? FOR UPDATE',[$t['id']])->fetch();if($locked['department_id']!==$t['department_id']){throw new HttpError(409,'MAIL_TICKET_MOVED');}if($u['status']!=='ACTIVE'||!$u['verified_at']||!$db->execute('SELECT 1 FROM identity_memberships WHERE user_id=? AND customer_id=? FOR UPDATE',[$u['id'],$r['customer_id']])->fetchColumn()){throw new HttpError(403,'MAIL_RECIPIENT_UNVERIFIED');}$p=$this->m->c->identity->repository->principal($u,['context'=>'client','customer_id'=>$r['customer_id'],'mfa_verified'=>true,'expiry'=>time()+60,'verified'=>0]);(new Authorization())->require($p,'support.view',$r['customer_id']);return $u['id'];
    }
    public function ready(array $p): string
    {
        $this->m->gate();$pre=$this->bound($p,'support.mail.ready');if(!$pre){return 'FAILED';}try{(new Outbox($this->m->c->db,new Queue($this->m->c->db)))->consume('support.mail.held.v1',$p['event_uuid'],function()use($p,$pre){try{$user=$this->recipient($pre);$status='HELD';}catch(HttpError){$user=null;$status='PERMANENT_FAILURE';}$r=$this->bound($p,'support.mail.ready',true);if(!$r){throw new \UnexpectedValueException();}if($r['status']!=='PENDING'||(int)$r['attempt_count']!==0){return;}$this->m->c->db->execute('UPDATE support_mail_outbound SET recipient_id=?,status=?,version=version+1 WHERE id=?',[$user,$status,$r['id']]);$this->m->event($r['id'],'OUTBOUND_HELD',new Principal('mail-worker',[]),Id::uuid(),['status'=>$status]);});}catch(\UnexpectedValueException){return 'FAILED';}return 'SUCCEEDED';
    }
    public function dispatch(array $p): string
    {
        $this->m->gate();$pre=$this->bound($p,'support.mail.dispatch');if(!$pre){return 'FAILED';}try{(new Outbox($this->m->c->db,new Queue($this->m->c->db)))->consume('support.mail.mock.v1',$p['event_uuid'],function()use($p,$pre){try{$recipient=$this->recipient($pre);}catch(HttpError){$recipient=null;}$r=$this->bound($p,'support.mail.dispatch',true);if(!$r){throw new \UnexpectedValueException();}$d=$r['dispatch'];if((int)$r['attempt_count']!==(int)$d['attempt_no']||$r['status']!=='PENDING'){throw new \UnexpectedValueException();}$mode=$d['mode'];if($recipient===null||$recipient!==$r['recipient_id']){$mode='PERMANENT_FAILURE';}
            $files=$this->m->c->db->execute('SELECT id,sha256,byte_count,scan_status,purged_at FROM support_mail_files WHERE message_id=? ORDER BY id',[$r['message_id']])->fetchAll();foreach($files as $f){if($f['purged_at']!==null){$mode='PERMANENT_FAILURE';}elseif($f['scan_status']!=='TEST_CLEAN'){$mode='HELD';}}
            if($mode==='ACCEPTED_BY_TRANSPORT'){foreach($files as $f){Factory::files($this->m)->store->read($f['id'],(int)$f['byte_count'],$f['sha256']);}$body=$this->m->c->db->execute('SELECT body_encrypted FROM support_messages WHERE id=?',[$r['message_id']])->fetchColumn();$digest=$this->m->hmac(CanonicalJson::encode(['body'=>$this->m->crypto->decrypt($body,'support-message:'.$r['message_id']),'files'=>$files]));$prior=$this->m->c->db->execute('SELECT recipient_id,content_hmac FROM support_mail_transport WHERE delivery_id=?',[$r['id']])->fetch();if($prior&&($prior['recipient_id']!==$r['recipient_id']||!hash_equals($prior['content_hmac'],$digest))){throw new \UnexpectedValueException();}if(!$prior){$this->m->c->db->execute("INSERT INTO support_mail_transport(delivery_id,recipient_id,content_hmac,outcome) VALUES (?,?,?,'ACCEPTED_BY_TRANSPORT')",[$r['id'],$r['recipient_id'],$digest]);}}
            $this->m->c->db->execute('INSERT INTO support_mail_attempts(id,delivery_id,attempt_no,outcome) VALUES (?,?,?,?)',[Id::uuid(),$r['id'],$d['attempt_no'],$mode]);$this->m->c->db->execute('UPDATE support_mail_outbound SET status=?,version=version+1 WHERE id=?',[$mode,$r['id']]);$this->m->event($r['id'],'MOCK_TRANSPORT_RESULT',new Principal('mail-worker',[]),Id::uuid(),['status'=>$mode]);});}catch(\UnexpectedValueException){return 'FAILED';}return 'SUCCEEDED';
    }
}
